use crate::{add_mod,mul_mod,pow_mod,sub_mod};
fn bit_reverse_permute(a:&mut[u64]){let n=a.len();let mut j=0usize;for i in 1..n{let mut bit=n>>1;while j&bit!=0{j^=bit;bit>>=1;}j^=bit;if i<j{a.swap(i,j);}}}
fn cyclic_ntt(a:&mut[u64],root:u64,q:u64,inverse:bool){let n=a.len();bit_reverse_permute(a);let mut len=2;while len<=n{let mut wl=pow_mod(root,(n/len) as u64,q);if inverse{wl=pow_mod(wl,q-2,q);}for i in (0..n).step_by(len){let mut w=1;for j in 0..len/2{let u=a[i+j];let v=mul_mod(a[i+j+len/2],w,q);a[i+j]=add_mod(u,v,q);a[i+j+len/2]=sub_mod(u,v,q);w=mul_mod(w,wl,q);}}len<<=1;}if inverse{let ni=pow_mod(n as u64,q-2,q);for x in a{*x=mul_mod(*x,ni,q);}}}
pub fn negacyclic_ntt(a:&[u64],q:u64,psi:u64,inverse:bool)->Vec<u64>{let n=a.len();assert!(n.is_power_of_two()&&n>0&&q>2&&a.iter().all(|&x|x<q));let pi=pow_mod(psi,q-2,q);let omega=mul_mod(psi,psi,q);let mut out=a.to_vec();if !inverse{let mut t=1;for x in &mut out{*x=mul_mod(*x,t,q);t=mul_mod(t,psi,q);}cyclic_ntt(&mut out,omega,q,false);}else{cyclic_ntt(&mut out,omega,q,true);let mut t=1;for x in &mut out{*x=mul_mod(*x,t,q);t=mul_mod(t,pi,q);}}out}
pub fn negacyclic_ntt_mul(a:&[u64],b:&[u64],q:u64,psi:u64)->Vec<u64>{assert_eq!(a.len(),b.len());let mut x=negacyclic_ntt(a,q,psi,false);let y=negacyclic_ntt(b,q,psi,false);for(u,v)in x.iter_mut().zip(y){*u=mul_mod(*u,v,q);}negacyclic_ntt(&x,q,psi,true)}
#[cfg(test)]mod tests{use super::*;use crate::{poly::negacyclic_mul,MODULI,ROOTS};#[test]fn candidate_roots_and_roundtrip(){let n=8192;for i in 0..4{let q=MODULI[i];let p=ROOTS[i];assert_eq!(pow_mod(p,(2*n)as u64,q),1);assert_eq!(pow_mod(p,n as u64,q),q-1);let mut a=vec![0;n];a[0]=1;a[1]=2;a[n-1]=q-1;let y=negacyclic_ntt(&a,q,p,false);assert_eq!(negacyclic_ntt(&y,q,p,true),a);}}#[test]fn ntt_matches_schoolbook(){let a=vec![1,2,3,4];let b=vec![5,6,7,8];assert_eq!(negacyclic_ntt_mul(&a,&b,97,64),negacyclic_mul(&a,&b,97));}}
